1	// In-process, time bounded lease registry with append-only log persistence.
2	// Time only moves when the injected clock moves; nothing expires on its own.
3	// Tokens are derived from the injected clock as well, never from wall time.
4	
5	import fs from 'node:fs';
6	
7	const LOG_VERSION = 1;
8	
9	export class LeaseTakenError extends Error {
10	  constructor(resource, holder) {
11	    super(`lease for resource ${String(resource)} is already held`);
12	    this.name = 'LeaseTakenError';
13	    this.code = LeaseTakenError.code;
14	    this.resource = resource;
15	    this.holder = holder ?? null;
16	  }
17	}
18	LeaseTakenError.code = 'LEASE_TAKEN';
19	
20	export class LogFileError extends Error {
21	  constructor(message, cause) {
22	    super(message);
23	    this.name = 'LogFileError';
24	    this.code = LogFileError.code;
25	    this.cause = cause ?? null;
26	  }
27	}
28	LogFileError.code = 'LOG_FILE_ERROR';
29	
30	// Binary min-heap ordered by (expiresAt, insertion order). Every live lease
31	// has a node in the queue; renewals push a fresh node and retire the old one,
32	// so reclaiming expired leases only walks entries that are actually due
33	// instead of scanning the whole table.
34	class ExpiryQueue {
35	  constructor() {
36	    this.nodes = [];
37	  }
38	
39	  get size() {
40	    return this.nodes.length;
41	  }
42	
43	  push(node) {
44	    const nodes = this.nodes;
45	    nodes.push(node);
46	    let i = nodes.length - 1;
47	    while (i > 0) {
48	      const parent = (i - 1) >> 1;
49	      if (expiresBefore(nodes[i], nodes[parent])) {
50	        [nodes[i], nodes[parent]] = [nodes[parent], nodes[i]];
51	        i = parent;
52	      } else {
53	        break;
54	      }
55	    }
56	  }
57	
58	  peek() {
59	    return this.nodes[0];
60	  }
61	
62	  pop() {
63	    const nodes = this.nodes;
64	    const top = nodes[0];
65	    const last = nodes.pop();
66	    if (nodes.length > 0) {
67	      nodes[0] = last;
68	      let i = 0;
69	      for (;;) {
70	        const left = i * 2 + 1;
71	        const right = left + 1;
72	        let next = i;
73	        if (left < nodes.length && expiresBefore(nodes[left], nodes[next])) {
74	          next = left;
75	        }
76	        if (right < nodes.length && expiresBefore(nodes[right], nodes[next])) {
77	          next = right;
78	        }
79	        if (next === i) {
80	          break;
81	        }
82	        [nodes[i], nodes[next]] = [nodes[next], nodes[i]];
83	        i = next;
84	      }
85	    }
86	    return top;
87	  }
88	}
89	
90	function expiresBefore(a, b) {
91	  if (a.expiresAt !== b.expiresAt) {
92	    return a.expiresAt < b.expiresAt;
93	  }
94	  return a.order < b.order;
95	}
96	
97	let registrySequence = 0;
98	
99	export function createRegistry({ ttlMs, clock = Date.now, logPath = null } = {}) {
100	  if (!Number.isFinite(ttlMs) || ttlMs <= 0) {
101	    throw new TypeError('ttlMs must be a positive finite number');
102	  }
103	  if (typeof clock !== 'function') {
104	    throw new TypeError('clock must be a function');
105	  }
106	
107	  const defaultTtlMs = ttlMs;
108	  // token -> { resource, holder, expiresAt, ttlMs, legacy, heapSeq }
109	  const leases = new Map();
110	  // Every token this instance knows about, including replayed credentials
111	  // that were already released or reclaimed, so a freshly minted token can
112	  // never reuse a dead credential's string.
113	  const knownTokens = new Set();
114	  // resource -> token of the lease currently occupying it
115	  const occupied = new Map();
116	  const expiryQueue = new ExpiryQueue();
117	
118	  const counters = {
119	    granted: 0,
120	    renewed: 0,
121	    released: 0,
122	    reclaimed: 0,
123	  };
124	
125	  // Per-instance identity makes tokens unique across registries living in the
126	  // same process; one instance can never present a token another owns.
127	  registrySequence += 1;
128	  const registryId = registrySequence;
129	  let tokenSequence = 0;
130	  let queueOrder = 0;
131	
132	  function mintToken(now) {
133	    // Pure candidate: nothing is committed until the event is on disk, so a
134	    // failed append rolls all the way back. Pids and instance ids can coincide
135	    // after a restart, so skip any sequence that collides with a credential
136	    // reconstructed from the log.
137	    let seq = tokenSequence;
138	    let token;
139	    do {
140	      seq += 1;
141	      token = `lease-${process.pid}-${registryId}-${seq}-${now.toString(36)}`;
142	    } while (knownTokens.has(token));
143	    return { token, seq };
144	  }
145	
146	  function enqueue(token, lease) {
147	    expiryQueue.push({
148	      token,
149	      expiresAt: lease.expiresAt,
150	      heapSeq: lease.heapSeq,
151	      order: queueOrder++,
152	    });
153	  }
154	
155	  function isLive(lease, now) {
156	    return lease !== undefined && lease.expiresAt > now;
157	  }
158	
159	  function appendEvent(event) {
160	    if (logPath === null) {
161	      return;
162	    }
163	    try {
164	      fs.appendFileSync(logPath, `${JSON.stringify(event)}\n`);
165	    } catch (cause) {
166	      throw new LogFileError(
167	        `failed to append to lease log at ${logPath}`,
168	        cause,
169	      );
170	    }
171	  }
172	
173	  function acquire(resource, holder, ttlMs = defaultTtlMs) {
174	    if (!Number.isFinite(ttlMs) || ttlMs <= 0) {
175	      throw new TypeError('ttlMs must be a positive finite number');
176	    }
177	    const now = clock();
178	    const currentToken = occupied.get(resource);
179	    if (currentToken !== undefined) {
180	      const current = leases.get(currentToken);
181	      if (isLive(current, now)) {
182	        throw new LeaseTakenError(resource, current.holder);
183	      }
184	      // Expired but not yet swept: the resource is free. The stale record is
185	      // dropped together with the new grant below (no event of its own).
186	    }
187	
188	    const { token, seq } = mintToken(now);
189	    const expiresAt = now + ttlMs;
190	    // Persist before touching any state: a failed write leaves the registry
191	    // exactly as it was before the call.
192	    appendEvent({
193	      v: LOG_VERSION,
194	      type: 'acquire',
195	      at: now,
196	      token,
197	      resource,
198	      holder,
199	      ttlMs,
200	      expiresAt,
201	    });
202	
203	    tokenSequence = seq;
204	    knownTokens.add(token);
205	    if (currentToken !== undefined) {
206	      occupied.delete(resource);
207	      leases.delete(currentToken);
208	    }
209	    const lease = {
210	      resource,
211	      holder,
212	      expiresAt,
213	      ttlMs,
214	      legacy: false,
215	      heapSeq: 0,
216	    };
217	    leases.set(token, lease);
218	    occupied.set(resource, token);
219	    enqueue(token, lease);
220	    counters.granted += 1;
221	
222	    return { resource, holder, token, expiresAt };
223	  }
224	
225	  function renew(token) {
226	    const lease = leases.get(token);
227	    if (lease === undefined || lease.legacy) {
228	      return false;
229	    }
230	    const now = clock();
231	    if (lease.expiresAt <= now) {
232	      return false;
233	    }
234	    const expiresAt = now + lease.ttlMs;
235	    appendEvent({ v: LOG_VERSION, type: 'renew', at: now, token, expiresAt });
236	
237	    lease.expiresAt = expiresAt;
238	    lease.heapSeq += 1;
239	    enqueue(token, lease);
240	    counters.renewed += 1;
241	    return true;
242	  }
243	
244	  function release(token) {
245	    const lease = leases.get(token);
246	    if (lease === undefined || lease.legacy) {
247	      return false;
248	    }
249	    const now = clock();
250	    if (lease.expiresAt <= now) {
251	      return false;
252	    }
253	    appendEvent({ v: LOG_VERSION, type: 'release', at: now, token });
254	
255	    // The record comes off immediately; its queued node retires lazily.
256	    leases.delete(token);
257	    if (occupied.get(lease.resource) === token) {
258	      occupied.delete(lease.resource);
259	    }
260	    counters.released += 1;
261	    return true;
262	  }
263	
264	  function sweep(now = clock()) {
265	    const due = [];
266	    while (expiryQueue.size > 0) {
267	      const node = expiryQueue.peek();
268	      if (node.expiresAt > now) {
269	        break;
270	      }
271	      expiryQueue.pop();
272	      const lease = leases.get(node.token);
273	      if (lease === undefined || lease.heapSeq !== node.heapSeq) {
274	        // Retired node: release, retake or renewal already superseded it.
275	        continue;
276	      }
277	      due.push(node);
278	    }
279	
280	    if (due.length === 0) {
281	      return [];
282	    }
283	
284	    try {
285	      appendEvent({
286	        v: LOG_VERSION,
287	        type: 'reclaim',
288	        at: now,
289	        items: due.map((node) => ({
290	          token: node.token,
291	          resource: leases.get(node.token).resource,
292	        })),
293	      });
294	    } catch (error) {
295	      // The write never happened: put the popped nodes back so the queue is
296	      // byte-for-byte the same as before the call.
297	      for (const node of due) {
298	        expiryQueue.push(node);
299	      }
300	      throw error;
301	    }
302	
303	    const freed = [];
304	    for (const node of due) {
305	      const lease = leases.get(node.token);
306	      leases.delete(node.token);
307	      if (occupied.get(lease.resource) === node.token) {
308	        occupied.delete(lease.resource);
309	        counters.reclaimed += 1;
310	        freed.push(lease.resource);
311	      }
312	    }
313	    return freed;
314	  }
315	
316	  function holder(resource) {
317	    const token = occupied.get(resource);
318	    if (token === undefined) {
319	      return null;
320	    }
321	    const lease = leases.get(token);
322	    if (!isLive(lease, clock())) {
323	      return null;
324	    }
325	    return lease.holder;
326	  }
327	
328	  function stats() {
329	    let live = 0;
330	    const now = clock();
331	    for (const token of occupied.values()) {
332	      const lease = leases.get(token);
333	      if (isLive(lease, now)) {
334	        live += 1;
335	      }
336	    }
337	    return {
338	      granted: counters.granted,
339	      renewed: counters.renewed,
340	      released: counters.released,
341	      reclaimed: counters.reclaimed,
342	      live,
343	    };
344	  }
345	
346	  replay();
347	
348	  return { acquire, renew, release, sweep, holder, stats };
349	
350	  function replay() {
351	    if (logPath === null) {
352	      return;
353	    }
354	
355	    let text;
356	    try {
357	      text = fs.readFileSync(logPath, 'utf8');
358	    } catch (cause) {
359	      if (cause.code === 'ENOENT') {
360	        // No log yet: start from an empty registry.
361	        return;
362	      }
363	      throw new LogFileError(
364	        `failed to read lease log at ${logPath}`,
365	        cause,
366	      );
367	    }
368	
369	    const lines = text.split('\n');
370	    for (let i = 0; i < lines.length; i += 1) {
371	      const line = lines[i];
372	      if (line.trim() === '') {
373	        continue;
374	      }
375	      let event;
376	      try {
377	        event = JSON.parse(line);
378	      } catch (cause) {
379	        throw new LogFileError(
380	          `corrupt lease log entry on line ${i + 1} of ${logPath}`,
381	          cause,
382	        );
383	      }
384	      replayEvent(event, i + 1);
385	    }
386	  }
387	
388	  function replayEvent(event, lineNumber) {
389	    if (event === null || typeof event !== 'object' || event.v !== LOG_VERSION) {
390	      throw new LogFileError(
391	        `unrecognized lease log version on line ${lineNumber} of ${logPath}`,
392	      );
393	    }
394	
395	    switch (event.type) {
396	      case 'acquire': {
397	        if (
398	          typeof event.token !== 'string' ||
399	          !Number.isFinite(event.ttlMs) ||
400	          !Number.isFinite(event.expiresAt)
401	        ) {
402	          throw new LogFileError(
403	            `corrupt acquire entry on line ${lineNumber} of ${logPath}`,
404	          );
405	        }
406	        const previousToken = occupied.get(event.resource);
407	        if (previousToken !== undefined && previousToken !== event.token) {
408	          // A later grant retook an expired, unswept resource.
409	          leases.delete(previousToken);
410	        }
411	        const lease = {
412	          resource: event.resource,
413	          holder: event.holder,
414	          expiresAt: event.expiresAt,
415	          ttlMs: event.ttlMs,
416	          // Credentials issued before this process started are void: the
417	          // lease keeps occupying the resource, but its token cannot
418	          // renew or release it.
419	          legacy: true,
420	          heapSeq: 0,
421	        };
422	        leases.set(event.token, lease);
423	        occupied.set(event.resource, event.token);
424	        knownTokens.add(event.token);
425	        enqueue(event.token, lease);
426	        counters.granted += 1;
427	        break;
428	      }
429	      case 'renew': {
430	        const lease = leases.get(event.token);
431	        if (
432	          typeof event.token !== 'string' ||
433	          !Number.isFinite(event.expiresAt)
434	        ) {
435	          throw new LogFileError(
436	            `corrupt renew entry on line ${lineNumber} of ${logPath}`,
437	          );
438	        }
439	        if (lease !== undefined) {
440	          lease.expiresAt = event.expiresAt;
441	          lease.heapSeq += 1;
442	          enqueue(event.token, lease);
443	        }
444	        counters.renewed += 1;
445	        break;
446	      }
447	      case 'release': {
448	        if (typeof event.token !== 'string') {
449	          throw new LogFileError(
450	            `corrupt release entry on line ${lineNumber} of ${logPath}`,
451	          );
452	        }
453	        const lease = leases.get(event.token);
454	        if (lease !== undefined) {
455	          leases.delete(event.token);
456	          if (occupied.get(lease.resource) === event.token) {
457	            occupied.delete(lease.resource);
458	          }
459	        }
460	        counters.released += 1;
461	        break;
462	      }
463	      case 'reclaim': {
464	        if (!Array.isArray(event.items)) {
465	          throw new LogFileError(
466	            `corrupt reclaim entry on line ${lineNumber} of ${logPath}`,
467	          );
468	        }
469	        for (const item of event.items) {
470	          if (item === null || typeof item !== 'object' ||
471	              typeof item.token !== 'string') {
472	            throw new LogFileError(
473	              `corrupt reclaim entry on line ${lineNumber} of ${logPath}`,
474	            );
475	          }
476	          const token = item.token;
477	          const lease = leases.get(token);
478	          if (lease !== undefined) {
479	            leases.delete(token);
480	            if (occupied.get(lease.resource) === token) {
481	              occupied.delete(lease.resource);
482	            }
483	          }
484	          counters.reclaimed += 1;
485	        }
486	        break;
487	      }
488	      default: {
489	        throw new LogFileError(
490	          `unknown lease log event type on line ${lineNumber} of ${logPath}`,
491	        );
492	      }
493	    }
494	  }
495	}
